CREATE TYPE "status_dokumen_enum" AS ENUM (
  'DRAFT_SURAT',
  'DRAFT_SPRINT',
  'FINAL'
);

CREATE TYPE "status_proses_enum" AS ENUM (
  'DRAFT',
  'MENUNGGU_APPROVAL',
  'REVISI',
  'DITOLAK',
  'SIAP_SPRINT',
  'SELESAI'
);

CREATE TYPE "status_approval_enum" AS ENUM (
  'REVISI',
  'APPROVE',
  'TOLAK'
);

CREATE TABLE "aturan_dinas_anggaran" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kode_dinas" varchar(3) UNIQUE NOT NULL,
  "nama_dinas" varchar(100) NOT NULL,
  "tipe_anggaran" varchar(30) NOT NULL,
  "aktif" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "master_surat" (
  "master_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nama_template" varchar(150) NOT NULL,
  "deskripsi" text,
  "isi_template" text,
  "aktif" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "master_alur_approval" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kode_alur" varchar(50) UNIQUE NOT NULL,
  "nama_alur" varchar(150) NOT NULL,
  "deskripsi" text,
  "aturan_dinas_anggaran_id" int NOT NULL,
  "kategori_surat" varchar(100),
  "versi" int NOT NULL DEFAULT 1,
  "aktif" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "tahap_approval" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kode_tahap" varchar(50) UNIQUE NOT NULL,
  "nama_tahap" varchar(150) NOT NULL,
  "deskripsi" text,
  "aktif" boolean NOT NULL DEFAULT true
);

CREATE TABLE "alur_approval_tahap" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "alur_approval_id" int NOT NULL,
  "tahap_approval_id" int NOT NULL,
  "urutan_tahap" int NOT NULL,
  "wajib" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "surat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "master_surat_id" int NOT NULL,
  "aturan_dinas_anggaran_id" int NOT NULL,
  "master_alur_approval_id" int NOT NULL,
  "kode_dinas_snapshot" varchar(3) NOT NULL,
  "tipe_anggaran_snapshot" varchar(30) NOT NULL,
  "versi_alur_snapshot" int NOT NULL DEFAULT 1,
  "kategori_dipa" varchar(100),
  "tanggal_kegiatan_from" timestamp NOT NULL,
  "tanggal_kegiatan_to" timestamp NOT NULL,
  "tempat_kegiatan" varchar(255) NOT NULL,
  "untuk" text,
  "kota_surat" varchar(100) NOT NULL,
  "tanggal_surat" date,
  "tujuan_surat" varchar(255),
  "status_dokumen" status_dokumen_enum NOT NULL DEFAULT 'DRAFT_SURAT',
  "status_proses" status_proses_enum NOT NULL DEFAULT 'DRAFT',
  "nomor_sprint" varchar(100) UNIQUE,
  "sprint_generated_at" timestamp,
  "versi_pengajuan" int NOT NULL DEFAULT 1,
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "created_by" varchar(100) NOT NULL,
  "updated_at" timestamp
);

CREATE TABLE "surat_dasar" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "nama_template" varchar(150),
  "deskripsi" text,
  "isi_surat" text,
  "urutan" int NOT NULL DEFAULT 1
);

CREATE TABLE "pegawai" (
  "nip" varchar(30) PRIMARY KEY,
  "nama_pegawai" varchar(150) NOT NULL,
  "pangkat_golongan" varchar(100),
  "jabatan" varchar(150),
  "nomor_urut" int,
  "aktif" boolean NOT NULL DEFAULT true
);

CREATE TABLE "surat_pegawai_langsung" (
  "surat_id" int NOT NULL,
  "pegawai_nip" varchar(30) NOT NULL,
  "nama_pegawai_snapshot" varchar(150) NOT NULL,
  "pangkat_golongan_snapshot" varchar(100),
  "jabatan_snapshot" varchar(150),
  "urutan" int NOT NULL,
  PRIMARY KEY ("surat_id", "urutan")
);

CREATE TABLE "lampiran" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "jenis_lampiran" varchar(100) NOT NULL,
  "nama_lampiran" varchar(255),
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "lampiran_pegawai" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "lampiran_id" int NOT NULL,
  "pegawai_nip" varchar(30) NOT NULL,
  "nama_pegawai_snapshot" varchar(150) NOT NULL,
  "pangkat_golongan_snapshot" varchar(100),
  "jabatan_snapshot" varchar(150),
  "nomor_urut" int NOT NULL
);

CREATE TABLE "tembusan" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "urutan_tembusan" int NOT NULL,
  "keterangan_tembusan" varchar(255) NOT NULL
);

CREATE TABLE "anggaran_perjalanan" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "kode_akun_anggaran" varchar(100),
  "nominal" decimal(15,2),
  "keterangan" text
);

CREATE TABLE "menimbang" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "pelaksanaan_kegiatan" text NOT NULL,
  "template_menimbang_surat" varchar(255),
  "urutan" int NOT NULL DEFAULT 1
);

CREATE TABLE "surat_tujuan" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "keterangan_tujuan" varchar(255) NOT NULL,
  "urutan" int NOT NULL DEFAULT 1
);

CREATE TABLE "approval" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "surat_id" int NOT NULL,
  "alur_approval_tahap_id" int NOT NULL,
  "status" status_approval_enum,
  "pejabat_pemeriksa" varchar(150),
  "catatan" text,
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "decided_at" timestamp
);

CREATE TABLE "approval_riwayat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "approval_id" int NOT NULL,
  "versi_pengajuan" int NOT NULL,
  "status" status_approval_enum NOT NULL,
  "catatan" text,
  "diputuskan_oleh" varchar(150) NOT NULL,
  "diputuskan_pada" timestamp NOT NULL DEFAULT (now())
);

CREATE UNIQUE INDEX ON "alur_approval_tahap" ("alur_approval_id", "urutan_tahap");

CREATE UNIQUE INDEX ON "alur_approval_tahap" ("alur_approval_id", "tahap_approval_id");

CREATE UNIQUE INDEX ON "surat_dasar" ("surat_id", "urutan");

CREATE UNIQUE INDEX ON "surat_pegawai_langsung" ("surat_id", "pegawai_nip");

CREATE UNIQUE INDEX ON "lampiran_pegawai" ("lampiran_id", "nomor_urut");

CREATE UNIQUE INDEX ON "lampiran_pegawai" ("lampiran_id", "pegawai_nip");

CREATE UNIQUE INDEX ON "tembusan" ("surat_id", "urutan_tembusan");

CREATE UNIQUE INDEX ON "menimbang" ("surat_id", "urutan");

CREATE UNIQUE INDEX ON "surat_tujuan" ("surat_id", "urutan");

CREATE UNIQUE INDEX ON "approval" ("surat_id", "alur_approval_tahap_id");

COMMENT ON COLUMN "aturan_dinas_anggaran"."kode_dinas" IS 'DLH atau DLF';

COMMENT ON COLUMN "aturan_dinas_anggaran"."tipe_anggaran" IS 'BERBASIS_ANGGARAN atau NON_ANGGARAN';

COMMENT ON COLUMN "approval"."status" IS '0=Revisi, 1=Approve, 2=Tolak, NULL=Pending';

COMMENT ON COLUMN "approval_riwayat"."status" IS '0=Revisi, 1=Approve, 2=Tolak';

ALTER TABLE "master_alur_approval" ADD FOREIGN KEY ("aturan_dinas_anggaran_id") REFERENCES "aturan_dinas_anggaran" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "alur_approval_tahap" ADD FOREIGN KEY ("alur_approval_id") REFERENCES "master_alur_approval" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "alur_approval_tahap" ADD FOREIGN KEY ("tahap_approval_id") REFERENCES "tahap_approval" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat" ADD FOREIGN KEY ("master_surat_id") REFERENCES "master_surat" ("master_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat" ADD FOREIGN KEY ("aturan_dinas_anggaran_id") REFERENCES "aturan_dinas_anggaran" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat" ADD FOREIGN KEY ("master_alur_approval_id") REFERENCES "master_alur_approval" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat_dasar" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat_pegawai_langsung" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat_pegawai_langsung" ADD FOREIGN KEY ("pegawai_nip") REFERENCES "pegawai" ("nip") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lampiran" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lampiran_pegawai" ADD FOREIGN KEY ("lampiran_id") REFERENCES "lampiran" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lampiran_pegawai" ADD FOREIGN KEY ("pegawai_nip") REFERENCES "pegawai" ("nip") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tembusan" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "anggaran_perjalanan" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "menimbang" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "surat_tujuan" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "approval" ADD FOREIGN KEY ("surat_id") REFERENCES "surat" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "approval" ADD FOREIGN KEY ("alur_approval_tahap_id") REFERENCES "alur_approval_tahap" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "approval_riwayat" ADD FOREIGN KEY ("approval_id") REFERENCES "approval" ("id") DEFERRABLE INITIALLY IMMEDIATE;
